The task supplies pathPrefix: "/api/messages/" for matching paths under that prefix. Using Convex 1.44.0, this is the only route:

```ts
import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
const http = httpRouter();
http.route({
  pathPrefix: "/api/messages/",
  method: "POST",
  handler: httpAction(async () => new Response(null, { status: 200 })),
});
export default http;
```
